import { gameRequest, type Env } from "./game";
import { z } from "zod";
// @ts-ignore generated by the Sites build
import assets from "./assets.generated.js";
export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url),
      headers = { "Cache-Control": "no-store" };
    if (url.pathname === "/api/network")
      return Response.json(
        { addresses: [], joinOrigin: url.origin },
        { headers },
      );
    if (url.pathname === "/api/health")
      return Response.json(
        { ok: true, transport: "https-polling" },
        { headers },
      );
    if (url.pathname === "/api/game") {
      if (request.method !== "POST")
        return new Response("Method not allowed", { status: 405 });
      if (
        request.headers.get("Origin") &&
        request.headers.get("Origin") !== url.origin
      )
        return new Response("Forbidden", { status: 403 });
      const body = await request.text();
      if (body.length > 16384)
        return new Response("Payload too large", { status: 413 });
      try {
        return Response.json(await gameRequest(JSON.parse(body), env), {
          headers,
        });
      } catch (error) {
        return Response.json(
          {
            ok: false,
            error:
              error instanceof z.ZodError
                ? "Invalid request."
                : "Unable to process request.",
          },
          { headers },
        );
      }
    }
    const asset =
      assets[url.pathname] ??
      (!url.pathname.includes(".") ? assets["/index.html"] : undefined);
    if (!asset) return new Response("Not found", { status: 404 });
    return new Response(
      Uint8Array.from(atob(asset.data), (c: string) => c.charCodeAt(0)),
      {
        headers: {
          "Content-Type": asset.type,
          "Cache-Control": url.pathname.startsWith("/assets/")
            ? "public,max-age=31536000,immutable"
            : "no-cache",
        },
      },
    );
  },
};
